import React, { useId } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';
import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
import { useUiCopy } from 'app/hooks/useUiCopy';

const ZIMM_COUNTRY_LANGUAGE_MISMATCH_RECIPE = 'ZimmCountryLanguageMismatch';

type ZimmCountryLanguageMismatchBaseProps = {
  /** Whether the prompt is open. Forwarded straight to `ZimmDrawer`. */
  isOpen: boolean;
  /**
   * Fires on every close path — backdrop click, close X, Esc (all three arrive via
   * `ZimmDrawer`'s own `onClose`, wired straight to this) — **and** the "stay" CTA's own
   * `onClick`. Always a direct, synchronous call from the interaction handler, never deferred to
   * `ZimmDrawer`'s `onCloseComplete`/exit-animation callback: the consumer writes a suppression
   * cookie inside `onDismiss` before performing a hard `window.location =` navigation elsewhere
   * in the flow, and a deferred callback risks losing that write to a fast subsequent page unload.
   */
  onDismiss: () => void;
};

export type ZimmCountryLanguageMismatchLocationProps = ZimmCountryLanguageMismatchBaseProps & {
  variant: 'location';
  inCountry: string;
  currentStore: string;
  targetStore: string;
  /**
   * Opaque target identifier — a site alias, a locale string, whatever the consumer's own
   * eligibility logic resolved. Never read or interpreted by this component; only ever handed
   * back, unmodified, to `onRedirect` when the act CTA fires.
   */
  target: unknown;
  onRedirect: (target: unknown) => void;
};

export type ZimmCountryLanguageMismatchLanguageProps = ZimmCountryLanguageMismatchBaseProps & {
  variant: 'language';
  inCountry: string;
  inLanguage: string;
  inCurrentLanguage: string;
  /** Same treatment as `ZimmCountryLanguageMismatchLocationProps['target']` — opaque, echoed
   *  back unmodified to `onSwitchLanguage`. */
  target: unknown;
  onSwitchLanguage: (target: unknown) => void;
};

export type ZimmCountryLanguageMismatchProps =
  | ZimmCountryLanguageMismatchLocationProps
  | ZimmCountryLanguageMismatchLanguageProps;

type ZimmCountryLanguageMismatchVariant = ZimmCountryLanguageMismatchProps['variant'];

/**
 * Widened, not narrowed — same technique and reason as `zimmProductCard/index.tsx`'s own
 * `ZimmProductCardVariationFields` (see that file's comment in full): every variant-specific
 * field is optional here purely so the render body below can destructure once with no
 * `if`/`switch` on `props.variant`. The exported discriminated union above is what actually
 * enforces correct usage at every call site — this cast only relaxes internal access inside this
 * file; it changes nothing about what a caller may legally pass in.
 */
type ZimmCountryLanguageMismatchVariationFields = Partial<
  Omit<ZimmCountryLanguageMismatchLocationProps, keyof ZimmCountryLanguageMismatchBaseProps | 'variant' | 'target'> &
    Omit<ZimmCountryLanguageMismatchLanguageProps, keyof ZimmCountryLanguageMismatchBaseProps | 'variant' | 'target'>
>;

type ZimmCountryLanguageMismatchConfig = {
  headingKey: string;
  headingFallback: string;
  bodyKey: string;
  bodyFallback: string;
  switchCtaKey: string;
  switchCtaFallback: string;
  stayCtaKey: string;
  stayCtaFallback: string;
};

/**
 * The extensibility mechanism this component is built around — every piece of copy that differs
 * between `location` and `language` comes from indexing into this table by `variant`, the same
 * technique `zimmProductCard/index.tsx`'s own `VARIATION_CONFIG` (line 316) uses for its
 * layout/visibility decisions. Zero `switch`/`if` on `props.variant` anywhere below (verified via
 * `grep -n "variant ===\|switch (variant)" index.tsx` — zero hits).
 *
 * Copy keys and English fallbacks are frozen by SFCC-831's decision record — do not invent new
 * ones. Sentence case throughout, never caps: `textStyle="heading3"` already carries
 * `textTransform: uppercase` (theme/foundation/typography.ts), so a capitalised fallback here
 * would double-transform.
 */
const VARIATION_CONFIG: Record<ZimmCountryLanguageMismatchVariant, ZimmCountryLanguageMismatchConfig> = {
  location: {
    headingKey: 'regional.locationPrompt.heading',
    headingFallback: "Looks like you're {inCountry}",
    bodyKey: 'regional.locationPrompt.body',
    bodyFallback:
      "You're currently shopping on {currentStore}. Switch to {targetStore} for local pricing, currency and shipping options.",
    switchCtaKey: 'regional.locationPrompt.cta.switch',
    switchCtaFallback: 'Switch to {targetStore}',
    stayCtaKey: 'regional.locationPrompt.cta.stay',
    stayCtaFallback: 'Stay on {currentStore}',
  },
  language: {
    headingKey: 'regional.languagePrompt.heading',
    headingFallback: 'Welcome to Zimmermann Europe',
    bodyKey: 'regional.languagePrompt.body',
    bodyFallback:
      "Welcome to Zimmermann Europe. We noticed you're {inCountry}, would you like to view our site {inLanguage}?",
    switchCtaKey: 'regional.languagePrompt.cta.switch',
    switchCtaFallback: 'View {inLanguage}',
    stayCtaKey: 'regional.languagePrompt.cta.stay',
    stayCtaFallback: 'Continue {inCurrentLanguage}',
  },
};

/**
 * Strips undefined entries so the cross-variant prop bag satisfies `useUiCopy`'s `t()` values
 * shape (`Record<string, string | number>` — no `undefined`). Safe to merge every display field
 * from both variants unconditionally: each `VARIATION_CONFIG` fallback above only ever
 * references the `{token}` names that exist for its own variant, so a field left undefined by
 * the *other* variant is simply never looked up by `interpolateUiCopy` (useUiCopy.ts).
 */
const definedValues = (values: Record<string, string | undefined>): Record<string, string> =>
  Object.fromEntries(Object.entries(values).filter((entry): entry is [string, string] => entry[1] !== undefined));

/**
 * Organism — the EU country/language mismatch prompt (SFCC-831), a modal `ZimmDrawer`
 * (`size="prompt"`) offering to switch storefront or language. Two variants share one component
 * and one layout: `location` (shopper's browser reports a different country than the current
 * storefront) and `language` (EU domestic storefront, browser reports a different language).
 * Composition modelled on `zimmWishlistAuthDrawer/index.tsx` — a drawer wrapper with no state of
 * its own, composing content underneath `ZimmDrawer`.
 *
 * **Deliberately ignorant of sites/locales/aliases.** `target` is never read or interpreted here
 * — it is handed back to `onRedirect`/`onSwitchLanguage` exactly as received when the act CTA
 * fires. The consumer (SFCC-689) owns all site/locale/alias logic; this component only knows how
 * to ask the question and report which answer the shopper picked.
 *
 * Both CTAs and the close button (the close button is `ZimmDrawer`'s own, already localised —
 * see `zimmDrawer/index.tsx`) render as real `ZimmButton`/`<button>` elements and inherit their
 * hover/focus-visible/active/disabled treatment entirely from `zimmButton.css.ts`;
 * `zimmCountryLanguageMismatch.css.ts` authors no interaction-state rule of its own — see that
 * file's own comment for why (Figma defines only `Step=–`, no other state, for this component).
 *
 * @param props see `ZimmCountryLanguageMismatchProps` — a discriminated union on `variant`.
 */
export const ZimmCountryLanguageMismatch = (props: ZimmCountryLanguageMismatchProps) => {
  const { isOpen, onDismiss, variant, target } = props;
  const { inCountry, currentStore, targetStore, inLanguage, inCurrentLanguage, onRedirect, onSwitchLanguage } =
    props as ZimmCountryLanguageMismatchVariationFields;

  const { t } = useUiCopy();
  const headingId = useId();
  const styles = useMultiStyleConfig(ZIMM_COUNTRY_LANGUAGE_MISMATCH_RECIPE, {});
  const config = VARIATION_CONFIG[variant];

  const values = definedValues({ inCountry, currentStore, targetStore, inLanguage, inCurrentLanguage });

  const heading = t(config.headingKey, config.headingFallback, values);
  const body = t(config.bodyKey, config.bodyFallback, values);
  const switchCta = t(config.switchCtaKey, config.switchCtaFallback, values);
  const stayCta = t(config.stayCtaKey, config.stayCtaFallback, values);

  // Exactly one of these two is ever defined for a given `variant` — enforced by the exported
  // discriminated union, not by this file. Optional-chaining both dispatches to whichever one a
  // caller actually supplied, with zero branching on `variant` itself.
  const handleAct = (): void => {
    onRedirect?.(target);
    onSwitchLanguage?.(target);
  };

  return (
    <ZimmDrawer isOpen={isOpen} onClose={onDismiss} size="prompt" labelledBy={headingId}>
      <chakra.div __css={styles.root}>
        <chakra.div __css={styles.content}>
          <chakra.h2 id={headingId} textStyle="heading3" color="var(--zimm-color-text-default)" margin={0}>
            {heading}
          </chakra.h2>
          <chakra.p textStyle="body2" color="var(--zimm-color-text-default)" margin={0}>
            {body}
          </chakra.p>
        </chakra.div>
        <chakra.div __css={styles.buttonGroup}>
          <ZimmButton variant="secondary" size="adaptive" fullWidth label={switchCta} onClick={handleAct} />
          <ZimmButton variant="primary" size="adaptive" fullWidth label={stayCta} onClick={onDismiss} />
        </chakra.div>
      </chakra.div>
    </ZimmDrawer>
  );
};

export default ZimmCountryLanguageMismatch;

import { breakpoints } from 'app/theme/foundation';

// SFCC-831 — layout only, for both the `location` and `language` variants of
// ZimmCountryLanguageMismatch (index.tsx). Figma confirms both variants share one layout at
// every breakpoint (SFCC-831 decisions.md #3 "Component structure": "Identical across both
// variants: Header + Body + Button-group"; #4 "Tablet content layout: None. Tablet content
// symbol is byte-identical to Desktop Small") — nothing here varies by variant; VARIATION_CONFIG
// in index.tsx handles the only thing that does (copy/callbacks).
//
// No `_hover`/`_active`/`_focusVisible`/`_disabled` rule exists in this file, deliberately —
// Figma's own properties for this component are Size/Variant/Step, and both banners are
// `Step=–` (SFCC-831 decisions.md #5: "Interaction states: None exist... States come from
// ZimmDrawer/ZimmButton recipes"). Every interactive element (both CTAs) renders as a real
// ZimmButton and inherits its own hover/press/focus/disabled treatment from zimmButton.css.ts —
// a second styling surface here would only drift from that over time (see
// .claude/rules/overrideStyling.md's "One canonical styling surface per component type").

export const ZimmCountryLanguageMismatch = {
  parts: ['root', 'content', 'buttonGroup'],
  baseStyle: {
    // Content→button-group gap (SFCC-831 decisions.md #3: "80px content→buttons desktop/tablet
    // (space/2000), 64px mobile (space/1600)") — --zimm-scale-5xl (spacing.ts: 5rem = 80px) and
    // --zimm-scale-4xl (spacing.ts: 4rem = 64px) are exact matches, no new token needed.
    //
    // Edge padding: ZimmDrawer's own `content` part (zimmDrawer.css.ts) carries none — every
    // drawer body supplies its own — and no Figma value for this component's own edge padding
    // was captured in SFCC-831's decision record (only the two gaps in this file were). Matches
    // the nearest real precedent for the same situation instead of inventing a number:
    // zimmAuthDrawerContent.css.ts's own `root.padding` (var(--zimm-scale-xl)) — a content
    // block's edge padding inside this same ZimmDrawer shell, used at size="small", the same
    // width class as size="prompt". Not independently confirmed against this component's own
    // Figma frame — flagged in the SFCC-831 Step B1 build report, not silently assumed.
    root: {
      display: 'flex',
      flexDirection: 'column',
      width: '100%',
      padding: 'var(--zimm-scale-xl)',
      gap: 'var(--zimm-scale-4xl)',
      [`@media (min-width: ${breakpoints.md})`]: {
        gap: 'var(--zimm-scale-5xl)',
      },
    },
    // Heading + body copy stack. Same "no captured Figma value" situation as root's padding
    // above — matches zimmAuthDrawerContent.css.ts's own `signupStack` gap
    // (var(--zimm-scale-m)), the same heading-plus-body-copy grouping concept in the same drawer
    // shell.
    content: {
      display: 'flex',
      flexDirection: 'column',
      width: '100%',
      gap: 'var(--zimm-scale-m)',
    },
    // A vertical CTA stack, not a horizontal row. SFCC-831 decisions.md #6's own arithmetic
    // ("Button-group is 120px desktop/tablet (2×52+16) and 96px mobile (2×40+16)") only resolves
    // against ZimmButton's own size="adaptive" HEIGHT (52px desktop / 40px mobile —
    // zimmButton/index.tsx's own doc comment), stacked with a 16px gap between them
    // (space/400) — --zimm-scale-m (1rem = 16px) is an exact match. A horizontal reading would
    // require each button to be exactly 52px/40px *wide*, which contradicts decisions.md #8's
    // own `min-w-80` (80px min-width) figure for the same buttons.
    buttonGroup: {
      display: 'flex',
      flexDirection: 'column',
      width: '100%',
      gap: 'var(--zimm-scale-m)',
    },
  },
};

